def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    player_count = 1 + len(alive)
    units = supply / float(WATER_REQ)
    scarcity = units < player_count

    highest_prev = 0
    stressed_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            stressed_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None and bid > highest_prev:
            highest_prev = bid

    if hp <= 2 or no_water >= 2:
        bid = min(budget, DAILY_SALARY * 0.98)
        return max(0, bid)

    if hp <= 4 or no_water >= 1:
        target = max(DAILY_SALARY * 0.72, highest_prev + 2)
        if scarcity:
            target = max(target, DAILY_SALARY * 0.82)
        bid = min(budget, target)
        return max(0, bid)

    if not scarcity:
        base = DAILY_SALARY * 0.26
        if highest_prev > 0:
            base = min(DAILY_SALARY * 0.5, max(base, highest_prev * 0.55))
        if stressed_opp >= len(alive) / 2.0 and len(alive) > 0:
            base *= 0.9
        bid = min(budget, base)
        return max(0, bid)

    base = DAILY_SALARY * 0.48
    if highest_prev > 0:
        if highest_prev >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * 0.35
        else:
            base = max(base, highest_prev + 1.5)

    if rich_opp >= max(1, len(alive) // 2):
        base += 4
    if stressed_opp >= max(1, len(alive) // 2):
        base -= 3

    if day_context['day'] >= 8:
        base += 6

    bid = min(budget, max(0, base))
    return bid

