def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        # If no one else is alive, take minimal competitive action.
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from opponents' previous_trace only.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many full units might be available.
    # Ensure integer indexing safety by explicit int().
    # (We don't rely on list indices, but keep safe patterns.)
    approx_units = int(max(0, min(MAX_SUPPLY, supply)) // float(WATER_REQ))
    if approx_units <= 0:
        approx_units = 1

    threshold_high = DAILY_SALARY * 0.85
    threshold_mid = DAILY_SALARY * 0.6

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If someone was bidding aggressively yesterday, we must not lose.
        if highest_prev_bid >= threshold_high:
            # If our hp is low or we are already close to failing, bid closer to their level.
            if hp <= 2 or no_water_days >= 1:
                target = highest_prev_bid + 2.0
            else:
                # Slightly above to win without fully matching.
                target = max(highest_prev_bid * 0.9, second_prev_bid + 1.0)
            bid = min(budget, target)
            return max(0.0, bid)

        # If bids were moderate, shade below the highest but still compete.
        if highest_prev_bid >= threshold_mid:
            target = max(highest_prev_bid * 0.75, second_prev_bid + 0.5)
            # If supply is tight, increase willingness.
            if supply <= float(MIN_SUPPLY) + 1.0:
                target *= 1.08
            bid = min(budget, target)
            return max(0.0, bid)

        # If they were timid, we can bid low to conserve budget.
        # Still scale with our hp/no_water_days to avoid running out.
        base = DAILY_SALARY * 0.35
        if hp <= 3:
            base = DAILY_SALARY * 0.55
        if no_water_days >= 2:
            base = DAILY_SALARY * 0.85
        # Supply tightness: bid slightly more.
        if supply <= float(MIN_SUPPLY) + 1.0:
            base *= 1.1
        bid = min(budget, base)
        return max(0.0, bid)

    # No prior bid info: default conservative strategy.
    base = DAILY_SALARY * 0.5
    if hp <= 2:
        base = DAILY_SALARY * 0.9
    elif hp <= 3:
        base = DAILY_SALARY * 0.65
    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.85)

    # If supply is low, bid more.
    if supply <= float(MIN_SUPPLY) + 1.0:
        base *= 1.15

    bid = min(budget, base)
    return max(0.0, bid)
